import csv

def analyse_grades(filepath):
    totals = {}
    counts = {}
    with open(filepath, 'r', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            subject = row['subject']
            score = float(row['score'])
            totals[subject] = totals.get(subject, 0) + score
            counts[subject] = counts.get(subject, 0) + 1
    averages = {s: totals[s]/counts[s] for s in totals}
    return averages

result = analyse_grades('grades.csv')
for subject, avg in result.items():
    print(f'{subject}: {avg:.1f}')

